export default function BangladeshMap({
  mapRef,
  unlockedDistricts = {},
  onDistrictClick,
}) {
  const [hoveredDistrict, setHoveredDistrict] = useState(null);
  const [selectedDistrict, setSelectedDistrict] = useState(null);
  const internalSvgRef = useRef(null);
  const svgRef = mapRef || internalSvgRef;

  // Clear any leftover GSAP inline styles on the SVG on mount
  useEffect(() => {
    if (svgRef.current) {
      gsap.set(svgRef.current, { clearProps: 'all' });
    }
  }, [svgRef]);

  // Render locked paths first, unlocked paths second, and the selected path on top
  // so its white highlight border & glow are never clipped by adjacent paths
  const sortedDistricts = [
    ...DISTRICT_PATHS.filter((d) => !unlockedDistricts[d.name] && d.name !== selectedDistrict),
    ...DISTRICT_PATHS.filter((d) => Boolean(unlockedDistricts[d.name]) && d.name !== selectedDistrict),
    ...DISTRICT_PATHS.filter((d) => d.name === selectedDistrict),
  ];

  const selectedDistrictData = selectedDistrict
    ? DISTRICT_PATHS.find((d) => d.name === selectedDistrict)
    : null;
  const activeBannerDistrict = hoveredDistrict || selectedDistrictData;
  const isBannerUnlocked = activeBannerDistrict ? Boolean(unlockedDistricts[activeBannerDistrict.name]) : false;
  const isSelectedUnlocked = selectedDistrict ? Boolean(unlockedDistricts[selectedDistrict]) : false;

  return (
    <div className="bg-slate-800/30 backdrop-blur-xl border border-slate-700/50 rounded-3xl p-4 md:p-8 w-full max-w-4xl mx-auto relative">
        {/* Top Bar: Legend & Live Hover / Selection Pill */}
        <div className="relative z-10 flex flex-wrap items-center justify-between gap-3 mb-4 pb-3 border-b border-slate-700/50">
          <div className="flex items-center gap-4 text-xs">
            <span className="inline-flex items-center gap-2 text-emerald-400 font-medium">
              <span className="w-3 h-3 rounded-sm bg-emerald-500" />
              Unlocked
            </span>
            <span className="inline-flex items-center gap-2 text-slate-400 font-medium">
              <span className="w-3 h-3 rounded-sm bg-slate-800 border border-slate-700" />
              Locked
            </span>
          </div>

          <div className="h-7 flex items-center">
            {activeBannerDistrict ? (
              <div
                className={`inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs font-semibold border transition-all duration-200 ease-out ${
                  isBannerUnlocked
                    ? 'bg-emerald-500/15 border-emerald-500/40 text-emerald-300'
                    : 'bg-slate-800/60 border-slate-700/60 text-slate-300'
                }`}
              >
                {isBannerUnlocked ? (
                  <Unlock className="w-3.5 h-3.5 text-emerald-400" />
                ) : (
                  <Lock className="w-3.5 h-3.5 text-slate-400" />
                )}
                <span>{activeBannerDistrict.name}</span>
                <span className="text-[10px] text-slate-400 font-normal">
                  · {isBannerUnlocked ? 'Unlocked' : 'Locked'}
                </span>
              </div>
            ) : (
              <span className="text-xs text-slate-400 inline-flex items-center gap-1.5">
                <MapPin className="w-3.5 h-3.5 text-emerald-400" />
                <span>ম্যাপ থেকে যেকোনো জেলা নির্বাচন করুন · Tap any district to select</span>
              </span>
            )}
          </div>
        </div>

        {/* Interactive 64-District SVG Map with Localized Zoom & Pan */}
        <div className="relative w-full rounded-2xl bg-slate-950/40 border border-slate-700/50">
          <TransformWrapper
            initialScale={1}
            minScale={1}
            maxScale={4}
            centerOnInit={true}
            wheel={{ step: 0.1 }}
            pinch={{ step: 5 }}
          >
            {({ zoomIn, zoomOut, resetTransform }) => (
              <>
                <TransformComponent
                  wrapperClass="!w-full"
                  contentClass="!w-full flex items-center justify-center"
                >
                  <svg
                    ref={svgRef}
                    viewBox="0 0 600 820"
                    className="w-full max-h-[680px] h-auto select-none overflow-visible transform-gpu will-change-transform origin-center"
                    role="img"
                    aria-label="Interactive map of the 64 districts of Bangladesh"
                  >
                    <g>
                      {sortedDistricts.map((district) => {
                        const isUnlocked = Boolean(unlockedDistricts[district.name]);
                        const isSelected = district.name === selectedDistrict;

                        let pathClass;
                        if (isSelected) {
                          pathClass = isUnlocked
                            ? 'fill-emerald-400 stroke-white stroke-[2] transition-colors duration-300 cursor-pointer'
                            : 'fill-slate-700 stroke-white stroke-[2] transition-colors duration-300 cursor-pointer';
                        } else if (isUnlocked) {
                          pathClass =
                            'fill-emerald-500 hover:fill-emerald-400 stroke-emerald-600 stroke-[0.5] hover:stroke-emerald-300 transition-colors duration-300 cursor-pointer';
                        } else {
                          pathClass =
                            'fill-slate-800 stroke-slate-700 stroke-[0.5] hover:fill-slate-700 transition-colors duration-300 cursor-pointer';
                        }

                        return (
                          <path
                            key={district.name}
                            d={district.d}
                            onMouseEnter={() => setHoveredDistrict(district)}
                            onMouseLeave={() => setHoveredDistrict(null)}
                            onClick={(e) => {
                              e.stopPropagation();
                              setSelectedDistrict(district.name);
                            }}
                            className={pathClass}
                          >
                            <title>
                              {`${district.name} (${isUnlocked ? 'Unlocked' : 'Locked'} — Tap to select)`}
                            </title>
                          </path>
                        );
                      })}
                    </g>

                    {/* District Labels for Unlocked, Hovered, or Selected District */}
                    <g className="pointer-events-none">
                      {DISTRICT_PATHS.map((district) => {
                        const isUnlocked = Boolean(unlockedDistricts[district.name]);
                        const isHovered = hoveredDistrict?.name === district.name;
                        const isSelected = selectedDistrict === district.name;
                        if (!isUnlocked && !isHovered && !isSelected) return null;

                        return (
                          <g key={`label-${district.name}`} transform={`translate(${district.cx}, ${district.cy})`}>
                            <circle
                              r={isSelected ? 4 : isUnlocked ? 3 : 2.5}
                              className={
                                isSelected
                                  ? 'fill-slate-50 stroke-emerald-500 stroke-2'
                                  : isUnlocked
                                    ? 'fill-slate-50 stroke-emerald-950 stroke-1'
                                    : 'fill-emerald-400'
                              }
                            />
                            <text
                              y={-8}
                              textAnchor="middle"
                              style={{ paintOrder: 'stroke' }}
                              className={`text-[10px] font-bold tracking-wide select-none stroke-slate-950 stroke-[3px] ${
                                isSelected || isUnlocked
                                  ? 'fill-slate-50'
                                  : 'fill-emerald-300'
                              }`}
                            >
                              {district.name}
                            </text>
                          </g>
                        );
                      })}
                    </g>
                  </svg>
                </TransformComponent>

                {/* Floating Zoom In / Zoom Out / Reset Controls (Bottom-Left) */}
                <div
                  className={`absolute left-4 z-20 flex flex-col gap-1.5 bg-slate-800/40 backdrop-blur-xl p-1.5 rounded-2xl border border-slate-700/50 shadow-xl transition-all duration-200 ease-out ${
                    selectedDistrict ? 'bottom-32 sm:bottom-28' : 'bottom-4'
                  }`}
                >
                  <button
                    type="button"
                    onClick={() => zoomIn()}
                    title="Zoom In"
                    aria-label="Zoom in"
                    className="p-2 rounded-xl bg-slate-800/40 hover:bg-emerald-500/20 text-slate-300 hover:text-emerald-400 border border-slate-700/50 hover:border-emerald-500/40 shadow-md transition-transform duration-200 ease-out hover:-translate-y-1 hover:shadow-emerald-500/30 active:scale-95 cursor-pointer"
                  >
                    <ZoomIn className="w-4 h-4" />
                  </button>
                  <button
                    type="button"
                    onClick={() => zoomOut()}
                    title="Zoom Out"
                    aria-label="Zoom out"
                    className="p-2 rounded-xl bg-slate-800/40 hover:bg-emerald-500/20 text-slate-300 hover:text-emerald-400 border border-slate-700/50 hover:border-emerald-500/40 shadow-md transition-transform duration-200 ease-out hover:-translate-y-1 hover:shadow-emerald-500/30 active:scale-95 cursor-pointer"
                  >
                    <ZoomOut className="w-4 h-4" />
                  </button>
                  <button
                    type="button"
                    onClick={() => resetTransform()}
                    title="Reset Zoom"
                    aria-label="Reset zoom"
                    className="p-2 rounded-xl bg-slate-800/40 hover:bg-emerald-500/20 text-slate-300 hover:text-emerald-400 border border-slate-700/50 hover:border-emerald-500/40 shadow-md transition-transform duration-200 ease-out hover:-translate-y-1 hover:shadow-emerald-500/30 active:scale-95 cursor-pointer"
                  >
                    <RotateCcw className="w-4 h-4" />
                  </button>
                </div>

                {/* Selected District Action Card (Overlay at bottom of map container) */}
                <AnimatePresence>
                  {selectedDistrict && (
                    <motion.div
                      key={selectedDistrict}
                      initial={{ y: 20, opacity: 0 }}
                      animate={{ y: 0, opacity: 1 }}
                      exit={{ y: 20, opacity: 0 }}
                      transition={{ duration: 0.2, ease: 'easeOut' }}
                      className="absolute inset-x-3 bottom-3 z-30 bg-slate-800/40 backdrop-blur-xl border border-slate-700/50 rounded-2xl shadow-xl p-6"
                    >
                      <div className="flex items-center justify-between gap-3">
                        {/* Left: Icon + District Name + Subtitle */}
                        <div className="flex items-center gap-3 min-w-0">
                          <div
                            className={`w-11 h-11 rounded-xl flex items-center justify-center flex-shrink-0 border ${
                              isSelectedUnlocked
                                ? 'bg-emerald-500/20 border-emerald-500/40 text-emerald-400'
                                : 'bg-slate-800/60 border-slate-700/50 text-slate-400'
                            }`}
                          >
                            {isSelectedUnlocked ? (
                              <Trophy className="w-5 h-5 text-emerald-400" />
                            ) : (
                              <Lock className="w-5 h-5 text-slate-400" />
                            )}
                          </div>
                          <div className="min-w-0">
                            <h4 className="text-base sm:text-lg font-extrabold tracking-tight text-slate-50 drop-shadow-md truncate">
                              {selectedDistrict}
                            </h4>
                            <p className="text-xs text-slate-300 drop-shadow-md truncate">
                              {isSelectedUnlocked
                                ? 'Official Expedition · গ্যালারি দেখতে ক্লিক করুন'
                                : 'Locked Expedition · আনলক করুন'}
                            </p>
                          </div>
                        </div>

                        {/* Right: Primary Action Button + Close (X) Button */}
                        <div className="flex items-center gap-2 flex-shrink-0">
                          {isSelectedUnlocked ? (
                            <button
                              type="button"
                              onClick={() => onDistrictClick(selectedDistrict)}
                              className="inline-flex items-center gap-1.5 px-4 py-2 bg-emerald-600 hover:bg-emerald-500 text-slate-50 drop-shadow-md text-xs sm:text-sm font-bold shadow-lg shadow-emerald-900/50 transition-transform duration-200 ease-out hover:-translate-y-1 hover:shadow-emerald-500/30 active:scale-95 rounded-xl cursor-pointer"
                            >
                              <span>Go to Gallery</span>
                              <ChevronRight className="w-4 h-4" />
                            </button>
                          ) : (
                            <button
                              type="button"
                              onClick={() => {
                                const target = selectedDistrict;
                                setSelectedDistrict(null);
                                onDistrictClick(target);
                              }}
                              className="inline-flex items-center gap-1.5 px-4 py-2 bg-emerald-600 hover:bg-emerald-500 text-slate-50 drop-shadow-md text-xs sm:text-sm font-bold shadow-lg shadow-emerald-900/50 transition-transform duration-200 ease-out hover:-translate-y-1 hover:shadow-emerald-500/30 active:scale-95 rounded-xl cursor-pointer"
                            >
                              <Unlock className="w-3.5 h-3.5 text-slate-50" />
                              <span>Unlock District</span>
                            </button>
                          )}

                          <button
                            type="button"
                            onClick={() => setSelectedDistrict(null)}
                            aria-label="Close district card"
                            title="Close"
                            className="p-2 rounded-xl text-slate-400 hover:text-slate-50 hover:bg-slate-700/50 border border-transparent hover:border-slate-700/50 transition-transform duration-200 ease-out hover:-translate-y-1 active:scale-95 cursor-pointer"
                          >
                            <X className="w-4 h-4" />
                          </button>
                        </div>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </>
            )}
          </TransformWrapper>
        </div>
    </div>
  );
}
